COM-13.worked_example_ar:
فصل التنقل والـ Snackbar عبر الـ Lambdas:
```kotlin
// شاشة نقية بدون NavController
@Composable fun DetailsScreen(onBack: () -> Unit, onShowMsg: (String) -> Unit)
// الـ Route يربط الـ NavController والـ Scaffold
@Composable fun DetailsRoute(navController: NavController) {
    val snackbarState = remember { SnackbarHostState() }
    val scope = rememberCoroutineScope()
    Scaffold(snackbarHost = { SnackbarHost(snackbarState) }) {
        DetailsScreen(onBack = { navController.popBackStack() }, onShowMsg = { scope.launch { snackbarState.showSnackbar(it) } })
    }
}
```

